 *
 * @throws FileSystemException
 */
@Test
public void test_close() throws FileSystemException {
    try (FileSystemManager fileSystemManager = new DefaultFileSystemManager()) {
        VFS.setManager(fileSystemManager);
        VFS.setManager(null);
